tool_input.newString:
const zipPath = path.resolve(__dirname, "../assets/compose/metabolism.zip");
const metabolismAlreadyLoaded = await page.getByText("Metabolism", { exact: true }).first().isVisible().catch(() => false);
if (!metabolismAlreadyLoaded) {
  const fileInput = page.locator('[id="compose.sketchpad.app.home.importKit"]');
  await expect(fileInput).toBeAttached({ timeout: 10000 });
  await fileInput.setInputFiles(zipPath);
  await fileInput.evaluate((el) => el.dispatchEvent(new Event("change", { bubbles: true })));
  await page.waitForTimeout(15000);
} else {
  console.log("[Panels] Metabolism already loaded, skipping import");
}
const metabolismText = page.getByText("Metabolism", { exact: true }).first();

